#!/usr/bin/env python3"""This script filters contigs clustered by trycycler cluster prior to trycycler reconcile to avoid areconciliation failureThis is done by:    - Removing contigs that are too long/short    - Removing contigs that cannot be circularized"""### ---------------------------------------- ###def parse_args():        # Load assembly        assembly_paths = argv[argv.index('--assemblies') + 1].split(',')        assemblies = {contig : seq for path in assembly_paths for contig,seq in load_fasta(path).items()}        return assemblies### ---------------------------------------- ###def load_fasta(path):        fasta = {}        for chrom in open(path).read().split('>'):                if not len(chrom):                        continue                chrom = chrom.split('\n')                chrom_name = chrom[0].split(' ')[0]                chrom_seq = ''.join(chrom[1:])                fasta[chrom_name] = chrom_seq        return fasta### ---------------------------------------- ###def length_filtering(contigs, max_diff=0.1):        filter_toggle = True        while filter_toggle:            contigs_length = {name : len(seq) for name,seq in contigs.items()}            outliers = []                for n1,l1 in contigs_length.items():                        for n2,l2 in contigs_length.items():                    length_diff = abs(1 - l1 / l2)                                if length_diff > max_diff:                                        outliers.append(n1)                    outliers.append(n2)                if len(outliers):                        outliers = [(o, outliers.count(o)) for o in set(outliers)]                        outliers.sort(key=lambda o: o[1], reverse=True)                        _ = contigs.pop(outliers[0][0], None)                else:                        filter_toggle = False        return contigs### ---------------------------------------- ###def circularization_filtering(contigs, max_add_seq=1000, max_add_seq_percent=0.05, max_trim_seq=50000, max_trim_seq_percent=0.1):    # Find starting sequence shared by all        base_seq = list(contigs.values())[0]        for kmer_len in [1000, 500, 250, 125]:                start_seq = ''            kmers = [base_seq[i : i + kmer_len] for i in range(0, len(base_seq) - kmer_len, 1)]                kmers = [k for k in kmers if kmers.count(k) == 1]                for k in kmers:                    hits = [(name, seq.count(k), reverse_complementary(seq).count(k)) for name,seq in contigs.items()]                        max_max_hit = max([max(h[1:]) for h in hits])            min_max_hit = min([max(h[1:]) for h in hits])                if max_max_hit > 1:                                # Multihit                continue                        elif min_max_hit == 0:                                # No hit in at least one contig                continue                        else:                                # Unique in each contig                                start_seq = k                                contigs_orientation = {name : '+' if forward > reverse else '-'                                       for name,forward,reverse in hits}                                break            if start_seq != '':                        break        ### Reorient contigs        reoriented_contigs = {name : contigs[name] if orientation == '+' else reverse_complementary(contigs[name])                          for name,orientation in contigs_orientation.items()}        ### Test circularization        circularization_impossible = []        for n1,s1 in reoriented_contigs.items():                can_be_circularized = False                for n2,s2 in reoriented_contigs.items():                if n1 == n2:                                continue                        min_l = min(len(s1), len(s2))                        max_gap = min(max_add_seq, round(max_add_seq_percent * min_l))            max_trim = - min(max_trim_seq, round(max_trim_seq_percent * min_l))                alignment, (ranges, _, _, identity, *_) = kmer_alignment(s1, s2)                        s1_start_on_s2 = min(ranges, key=lambda r: r[0])            s1_end_on_s2 = max(ranges, key=lambda r: r[1])                        gap_or_overlap = s1_start_on_s2[2] - s1_end_on_s2[3]                        if gap_or_overlap >= 0 and gap_or_overlap < max_gap:                                can_be_circularized = True                                break                        elif gap_or_overlap < 0 and gap_or_overlap > max_trim:                                can_be_circularized = True                                break                        else:                                continue                if not can_be_circularized:                        circularization_impossible.append(n1)        ### Remove contigs that cannot be circularized (N.B. using contigs, not reoriented_contigs)        filtered_contigs = {name : seq for name,seq in contigs.items() if name not in circularization_impossible}        return filtered_contigs### ---------------------------------------- ###def extract_kmers(seq, k=21):        kmers = list(set([seq[i : i + k] for i in range(0, len(seq) - k, 1)]))        return kmers### ---------------------------------------- ###def reverse_complementary(seq, seq_type='DNA'):        if seq_type == 'DNA':                rev_comp = seq[::-1].lower().replace('a', 'T').replace('t', 'A').replace('g', 'C').replace('c', 'G')        elif seq_type == 'RNA':                rev_comp = seq[::-1].lower().replace('a', 'U').replace('u', 'A').replace('g', 'C').replace('c', 'G')        else:                rev_comp = ''            return rev_comp### ---------------------------------------- ###def kmer_alignment(query, subject, kmer_size=31, min_anchor_kmers=50, matches_reward=1, mismatches_penalty=-1, gap_penalty=0):        """    Local alignment using k-mers matching    """    # All uppercase        query, subject = query.upper(), subject.upper()        # Find shared kmers as anchors    # N.B. using ".index()" when computing match_offsets to make algorithm greedy        query_kmers = [query[i : i + kmer_size] for i in range(0, len(query) - kmer_size + 1, 1)]        subject_kmers = [subject[i : i + kmer_size] for i in range(0, len(subject) - kmer_size + 1, 1)]        match_offsets = np.array([(n, subject_kmers.index(qk), subject_kmers.index(qk) - n)                              for n,qk in enumerate(query_kmers)                              if qk in subject_kmers])        # Align        if not len(match_offsets):                return np.array([[], [], []]), (0, 0, 0, 0, 0)        else:                # Align using anchors                alignment = np.repeat('-', 3 * len(query)).reshape((3, len(query)))                alignment[0,] = list(query)                ranges = []                for o in np.unique(match_offsets[:, 2]):                        matches_sub = match_offsets[match_offsets[:, 2] == o,].copy()                        matches_sub = matches_sub[np.argsort(matches_sub[:, 0])]                        if matches_sub.shape[0] < min_anchor_kmers:                                continue                        q_start, q_end = matches_sub[0, 0], matches_sub[-1, 0]                        s_start, s_end = matches_sub[0, 1], matches_sub[-1, 1]                        alignment[2, q_start : q_end + kmer_size] = list(subject[s_start : s_end + kmer_size])                    ranges.append((q_start, q_end + kmer_size, s_start, s_end + kmer_size))                # Fill in alignment graph                alignment[1, alignment[0,] == alignment[2,]] = '|'                alignment[1, (alignment[0,] != alignment[2,]) & (alignment[2,] != '-')] = ' '                # Alignment stats                alignment_score = (matches_reward * np.sum(alignment[1,] == '|') +                           mismatches_penalty * np.sum(alignment[1,] == ' ') +                           gap_penalty * np.sum(alignment[1,] == '-'))                query_coverage = 100 * np.sum(alignment[1,] != '-') / alignment.shape[1]                alignment_length = np.where(alignment[1,] != '-')[0]        alignment_length = alignment_length[-1] - alignment_length[0] + 1                identity = 100 * np.sum(alignment[1,] == '|') / alignment_length                norm_alignment_score = alignment_score * (alignment_length / alignment.shape[1])                return alignment, (ranges, alignment_length, query_coverage, identity, alignment_score, norm_alignment_score)### ---------------------------------------- ###def structure_fasta(seq, seq_name='Seq', line_chars=80):            fasta = [f'>{seq_name}']        for i in range(0, len(seq), line_chars):                fasta.append(seq[i : i + line_chars])        fasta = '\n'.join(fasta)        return fasta### ------------------MAIN------------------ ###import numpy as npfrom sys import argv### Load assembliesassemblies = parse_args()### Length filteringmax_length_diff = 0.1 # Default for trycycler reconcileassemblies = length_filtering(assemblies, 0.1)### Circularization filteringmax_add_seq, max_add_seq_percent = 1000, 0.05 # Default for trycycler reconcilemax_trim_seq, max_trim_seq_percent = 50000, 0.1 # Default for trycycler reconcileassemblies = circularization_filtering(assemblies, max_add_seq, max_add_seq_percent, max_trim_seq, max_trim_seq_percent)### Export good fastafor a_name, a_seq in assemblies.items():        fasta_txt = structure_fasta(a_seq, a_name, len(a_seq))        with open(f'{a_name}.fasta', 'w') as fasta_out:                fasta_out.write(fasta_txt)